const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体示意' },
      { kind: 'text', payload: '由静止释放' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v、g 均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cx = w * 0.42;
    var ballR = Math.max(14, Math.min(w, h) * 0.07);
    var ballY = h * 0.38;
    var releaseY = h * 0.16;
    var guideBottom = ballY - ballR - 8;
    var vStartY = ballY + ballR + 10;
    var vEndY = Math.min(h - 34, vStartY + h * 0.34);
    var gX = cx + Math.max(70, w * 0.18);
    var gStartY = ballY + 4;
    var gEndY = Math.min(h - 34, gStartY + h * 0.30);
    var guide = visualSdk.polyline([[cx, releaseY], [cx, guideBottom]]);
    var ball = visualSdk.circle(cx, ballY, ballR);
    var vArrow = visualSdk.arrow(cx, vStartY, cx, vEndY, {});
    var gArrow = visualSdk.arrow(gX, gStartY, gX, gEndY, {});
    return {
      schemaVersion: 1,
      sceneId: 'free-fall-schematic',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'guide', commands: guide },
        { id: 'ball', commands: ball },
        { id: 'v-arrow', commands: vArrow },
        { id: 'g-arrow', commands: gArrow }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'guide', stroke: '#8a96a8', strokeWidth: 1.5, strokeDasharray: '4 5' },
        { type: 'path', pathId: 'ball', fill: '#ffffff', stroke: '#26354a', strokeWidth: 2 },
        { type: 'path', pathId: 'v-arrow', stroke: '#1f5fbf', strokeWidth: 2.5 },
        { type: 'path', pathId: 'g-arrow', stroke: '#c0392b', strokeWidth: 2.5 },
        { type: 'label', text: '自由落体示意', x: w * 0.5, y: 30, fontSize: 18, textAnchor: 'middle', fill: '#26354a', fontWeight: 'bold' },
        { type: 'label', text: '由静止释放', x: cx + 10, y: releaseY + 4, fontSize: 13, textAnchor: 'start', fill: '#5b6675' },
        { type: 'label', text: 'v', x: cx + 10, y: vEndY - 4, fontSize: 16, textAnchor: 'start', fill: '#1f5fbf', fontWeight: 'bold' },
        { type: 'label', text: 'g', x: gX + 10, y: gEndY - 4, fontSize: 16, textAnchor: 'start', fill: '#c0392b', fontWeight: 'bold' },
        { type: 'label', text: 'v、g 均竖直向下', x: w * 0.5, y: h - 18, fontSize: 13, textAnchor: 'middle', fill: '#5b6675' }
      ] }
    };
  }
};
